import{_ as e,o,c as r,a2 as s}from"./chunks/framework.CqdVOxXJ.js";const n="/rakkii-cars-guide/screenshots/05-lane-1-private-walk-in-jobs/08-job-progress.png",a="/rakkii-cars-guide/screenshots/05-lane-1-private-walk-in-jobs/01-intake-checklist.png",i="/rakkii-cars-guide/screenshots/05-lane-1-private-walk-in-jobs/04-new-job.png",l="/rakkii-cars-guide/screenshots/05-lane-1-private-walk-in-jobs/05-work-lines.png",d="/rakkii-cars-guide/screenshots/05-lane-1-private-walk-in-jobs/02-portal-approve.png",h="/rakkii-cars-guide/screenshots/05-lane-1-private-walk-in-jobs/06-under-repair-qc-gate.png",g="/rakkii-cars-guide/screenshots/05-lane-1-private-walk-in-jobs/09-more-papers.png",c="/rakkii-cars-guide/screenshots/05-lane-1-private-walk-in-jobs/07-pay-money.png",p="/rakkii-cars-guide/screenshots/05-lane-1-private-walk-in-jobs/03-release-checklist.png",q=JSON.parse('{"title":"5. Lane 1 — Private / walk-in jobs","description":"","frontmatter":{},"headers":[],"relativePath":"chapters/05-lane-1-private-walk-in-jobs.md","filePath":"chapters/05-lane-1-private-walk-in-jobs.md","lastUpdated":1793403538000}'),u={name:"chapters/05-lane-1-private-walk-in-jobs.md"};function m(k,t,b,f,w,y){return o(),r("div",null,[...t[0]||(t[0]=[s(`<h1 id="_5-lane-1-—-private-walk-in-jobs" tabindex="-1">5. Lane 1 — Private / walk-in jobs <a class="header-anchor" href="#_5-lane-1-—-private-walk-in-jobs" aria-label="Permalink to &quot;5. Lane 1 — Private / walk-in jobs&quot;">​</a></h1><p><strong>For:</strong> Shop Owner · <strong>Hubs:</strong> Workshop, Finance · <strong>Nature:</strong> Private · <strong>Job type:</strong> Retail</p><p>This is the base flow every other lane builds on. A private customer drives in (or calls, messages, books online), you quote, collect a down payment, repair, invoice, collect the balance and release.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Intake forms → New job (Booked) → Quote → Customer approves → Down payment</span></span>
<span class="line"><span>→ Assign technician → Under repair → Quality check → Ready for pickup</span></span>
<span class="line"><span>→ Customer invoice → Final payment → Release checklist → Released → Done</span></span></code></pre></div><h2 id="status-map" tabindex="-1">Status map <a class="header-anchor" href="#status-map" aria-label="Permalink to &quot;Status map {#status-map}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th><th>Main next step (button)</th></tr></thead><tbody><tr><td><strong>New inquiry</strong></td><td>Lead from web, Messenger or the sales pipeline</td><td><strong>Confirm booking</strong></td></tr><tr><td><strong>Booked</strong></td><td>Car or appointment confirmed</td><td><strong>Start work</strong> (retail job that needs no canvass), otherwise <strong>For canvass</strong> / <strong>Mark quoted</strong></td></tr><tr><td><strong>For canvass</strong></td><td>Parts prices being gathered</td><td><strong>Mark quoted</strong></td></tr><tr><td><strong>Quoted</strong></td><td>Estimate given</td><td><strong>Start work</strong></td></tr><tr><td><strong>Waiting for LOA</strong> / <strong>Authorized</strong></td><td>Insurance only (<a href="/rakkii-cars-guide/chapters/06-lane-2-insurance-claims-and-loa">Chapter 6</a>)</td><td><strong>Mark authorized</strong> → <strong>Start work</strong></td></tr><tr><td><strong>Under repair</strong></td><td>In the bay</td><td><strong>Send to QC</strong> (main button until the 4 QC photos are in), then <strong>Ready for pickup</strong></td></tr><tr><td><strong>Waiting for parts</strong></td><td>Paused for an ordered part</td><td><strong>Parts in — back to shop</strong></td></tr><tr><td><strong>Quality check</strong></td><td>Being inspected</td><td><strong>Ready for pickup</strong> / <strong>Back to shop</strong></td></tr><tr><td><strong>On hold</strong></td><td>Paused with a reason</td><td><strong>Resume</strong> / <strong>Cancel job</strong></td></tr><tr><td><strong>Ready for pickup</strong></td><td>Done, waiting for the customer</td><td><strong>Release car</strong></td></tr><tr><td><strong>Released</strong></td><td>Car has left, but money or checklist items may still be open</td><td><strong>Mark as done</strong> (or <strong>Mark invoiced</strong>)</td></tr><tr><td><strong>Invoiced</strong></td><td>Optional bookkeeping step after release</td><td><strong>Mark as done</strong></td></tr><tr><td><strong>Done</strong></td><td>Nothing left on the job (this used to be called <strong>Closed</strong>)</td><td>—</td></tr><tr><td><strong>Cancelled</strong> / <strong>No-show</strong></td><td>Ended without work (reason required to cancel)</td><td>—</td></tr></tbody></table><p>Every status change is kept in the job&#39;s <strong>Status log</strong> with who moved it and when.</p><h3 id="next-step" tabindex="-1">The next-step banner <a class="header-anchor" href="#next-step" aria-label="Permalink to &quot;The next-step banner {#next-step}&quot;">​</a></h3><p>Every job shows one blue banner under the plate that says what to do next, for example &quot;Add quote lines, start canvass, or start work.&quot;, &quot;Collect PHP 800.00 from customer before release.&quot; or &quot;Release the car.&quot; It changes as the job moves. When something blocks the main step, the banner names it instead:</p><table tabindex="0"><thead><tr><th>Banner</th><th>What it means</th></tr></thead><tbody><tr><td>&quot;The customer sent a payment proof. Confirm or reject it.&quot;</td><td>A GCash/Maya screenshot from the Customer Portal is waiting (see <a href="#_5-5-record-the-50-down-payment">5.5</a>)</td></tr><tr><td>&quot;Take the missing QC photos (Rear, Left side (LS)). 2 of 4 done.&quot;</td><td>Ready for pickup is locked until the QC photos are in</td></tr><tr><td>&quot;The customer approved the estimate online. Start work.&quot;</td><td>The customer pressed <strong>Approve estimate</strong> on the Customer Portal</td></tr><tr><td>&quot;The customer declined the estimate online. Revise the quote or cancel the job.&quot;</td><td>The customer pressed <strong>Decline estimate</strong></td></tr><tr><td>&quot;Collect PHP … from customer before release.&quot;</td><td>The customer still owes and the car is held</td></tr></tbody></table><p>Technicians see their own version of the banner, for example &quot;Finish the bay checklist (1 step left), then send to QC.&quot; (<a href="/rakkii-cars-guide/chapters/02-technician-daily-guide">Chapter 2</a>).</p><h3 id="progress" tabindex="-1">Status, steps and what&#39;s left <a class="header-anchor" href="#progress" aria-label="Permalink to &quot;Status, steps and what&#39;s left {#progress}&quot;">​</a></h3><p>The top of every job tells you where it is without opening each tab:</p><ul><li><strong>Status banner</strong> — the job&#39;s status in words, with when and by whom it last moved, for example &quot;Released · car is out&quot; and &quot;Oct 30, 2026, 3:21 PM by …&quot;. On-hold and cancel reasons show here too.</li><li><strong>Steps bar</strong> — &quot;Step 6 of 7 · Paid&quot;. Tap it to see all seven steps with their dates: <strong>Intake</strong>, <strong>Approved</strong>, <strong>Work done</strong>, <strong>QC passed</strong>, <strong>Released</strong>, <strong>Paid</strong>, <strong>Done</strong>.</li><li><strong>Tab marks</strong> — ✓ means the tab is finished, ● means it needs you. They show on <strong>Quote</strong>, <strong>Parts buy</strong>, <strong>Work</strong>, <strong>Pay</strong> and <strong>Release</strong>.</li><li><strong>Not done yet</strong> — once the car is out, a box lists what is still open: checklist items, the customer and insurer balances, unpaid suppliers and a payment proof to review. It does not show a count; it just lists the items.</li></ul><p>Technicians see no money in the banner, the steps or the list.</p><p><img src="`+n+'" alt="A released job: status banner, Not done yet list, the steps opened with their dates, Mark as done and the tab marks"></p><h3 id="money-wording" tabindex="-1">Money wording <a class="header-anchor" href="#money-wording" aria-label="Permalink to &quot;Money wording {#money-wording}&quot;">​</a></h3><p>The customer&#39;s balance reads differently as the job moves, so a fresh job never looks like a debt:</p><table tabindex="0"><thead><tr><th>Stage</th><th>Wording</th></tr></thead><tbody><tr><td>Before work is approved</td><td><strong>Quote ₱…</strong></td></tr><tr><td>Work approved, car still in the shop</td><td><strong>To collect ₱…</strong></td></tr><tr><td>Car is out</td><td><strong>Customer owes ₱…</strong></td></tr></tbody></table><p>The same wording is used on the job, the Shop board cards and the board&#39;s <strong>What&#39;s left</strong> pop-up.</p><h2 id="_5-1-before-the-car-is-touched-intake-paperwork" tabindex="-1">5.1 Before the car is touched: intake paperwork <a class="header-anchor" href="#_5-1-before-the-car-is-touched-intake-paperwork" aria-label="Permalink to &quot;5.1 Before the car is touched: intake paperwork&quot;">​</a></h2><h3 id="undertaking-vehicle-intake-checklist-workshop-forms-intake" tabindex="-1">Undertaking &amp; Vehicle intake checklist (<code>/workshop/forms/intake</code>) <a class="header-anchor" href="#undertaking-vehicle-intake-checklist-workshop-forms-intake" aria-label="Permalink to &quot;Undertaking &amp; Vehicle intake checklist (`/workshop/forms/intake`)&quot;">​</a></h3><ol><li>Go to <strong>Workshop › Forms</strong> and on <strong>Undertaking and vehicle intake checklist</strong> press <strong>Start from job</strong> (after the job exists) or <strong>Open</strong> for a blank.</li><li>Fill the undertaking blanks (date, owner name, make/model, plate). The wording itself is fixed.</li><li>On the <strong>Vehicle intake checklist</strong>: customer, address, date, color, model/unit, odometer, plate; <strong>tap each damaged panel</strong>; set <strong>Fuel level</strong>; mark each item <strong>Present / Not present</strong>; add <strong>Remarks</strong>.</li><li>Press <strong>Save on job</strong> (when started from a job), then <strong>Print</strong> for signatures (customer, inspected by).</li></ol><h3 id="vehicle-pick-up-delivery-waiver-workshop-forms-vd-waiver" tabindex="-1">Vehicle Pick-up &amp; Delivery Waiver (<code>/workshop/forms/vd-waiver</code>) <a class="header-anchor" href="#vehicle-pick-up-delivery-waiver-workshop-forms-vd-waiver" aria-label="Permalink to &quot;Vehicle Pick-up &amp; Delivery Waiver (`/workshop/forms/vd-waiver`)&quot;">​</a></h3><p>Use it when a driver picks up or delivers the customer&#39;s car outside the shop. It covers customer and vehicle information, pickup/delivery addresses and times, a pre-delivery damage diagram, condition checks, terms and signatures. Fill it, then <strong>Print</strong>. It is also on the job&#39;s Quote and Work tabs as <strong>Pickup/Delivery waiver</strong>.</p><p><img src="'+a+'" alt="Vehicle intake checklist with car panel diagram"></p><h2 id="_5-2-create-the-job-workshop-jobs-new" tabindex="-1">5.2 Create the job (<code>/workshop/jobs/new</code>) <a class="header-anchor" href="#_5-2-create-the-job-workshop-jobs-new" aria-label="Permalink to &quot;5.2 Create the job (`/workshop/jobs/new`)&quot;">​</a></h2><p>The form is in the order you get the information at the counter: customer, car, work, then how the job came in.</p><ol><li>Press <strong>New job</strong> (Workshop pin).</li><li><strong>Customer</strong> — type two letters of the <strong>Customer name</strong> to find someone on file, or enter a new name, <strong>Mobile</strong> (required), <strong>Email</strong> and <strong>Customer category</strong> (Person). <ul><li>When you pick a customer who is already on file, their cars appear as chips under the name. Tap a car to fill <strong>Plate</strong>, <strong>Make</strong>, <strong>Model</strong> and <strong>Year</strong>, or <strong>New car</strong> to type a different one.</li></ul></li><li><strong>Vehicle</strong> — <strong>Plate</strong> (required), <strong>Make</strong>, <strong>Model</strong>, <strong>Year</strong>.</li><li><strong>Work</strong> — <strong>Work category</strong>, <strong>Target date</strong> (when the repair should be done), <strong>Services</strong> and <strong>Notes</strong>.</li><li><strong>How the job came in</strong><ul><li><strong>How they arrived</strong>: Walk-in, Phone, Messenger, Website or Sales.</li><li><strong>Job type</strong>: Retail. <strong>Nature</strong>: Private. Job type and nature follow each other (Insurance ↔ Insurance, Retail ↔ Private), so set one and check the other.</li><li><strong>Tax</strong>: VAT or Non-VAT (shop default pre-selected).</li><li><strong>Sales advisor</strong> (optional, never earns commission) and <strong>Referred by (staff)</strong> (optional, earns in-house commission unless the channel is a no-commission channel).</li><li><strong>Referred by (outside agent)</strong> and <strong>Agent fee (₱)</strong> only if an outside agent sent the customer; leave the fee blank to use the shop default.</li></ul></li><li>Press <strong>Create job</strong>. A desk-created job starts at <strong>Booked</strong> and gets a job reference (for example <code>JOB-20261029-6945</code>) and a customer pay link.</li></ol><p>The appointment day (when the car comes in) is separate from the target date. Set it on <strong>Overview › Appointment</strong> if the customer is booked for a later day.</p><p><img src="'+i+'" alt="New job form with Customer, Vehicle and Work filled"></p><h2 id="_5-3-build-the-quote" tabindex="-1">5.3 Build the quote <a class="header-anchor" href="#_5-3-build-the-quote" aria-label="Permalink to &quot;5.3 Build the quote&quot;">​</a></h2><h3 id="work-lines-work-tab" tabindex="-1">Work lines (Work tab) <a class="header-anchor" href="#work-lines-work-tab" aria-label="Permalink to &quot;Work lines (Work tab)&quot;">​</a></h3><ol><li>Open the job&#39;s <strong>Work</strong> tab, card <strong>Work lines</strong>.</li><li>For each line choose <strong>Kind</strong> (Labor, Part, Paint, Fee, Other). For parts pick a <strong>Catalog part</strong> (shows on hand and low stock) or <strong>One-off instead</strong>.</li><li>Enter <strong>Description</strong>, <strong>Qty</strong>, <strong>Cost</strong> (what it costs the shop) and <strong>Sell</strong> (customer price). <strong>Who pays</strong> = Customer.</li><li><strong>Add line</strong>. Untick or remove lines the customer did not approve.</li></ol><p>If the parts need supplier prices first, tick <strong>Needs canvass</strong> / <strong>Needs parts buy</strong> on <strong>Overview</strong> (retail jobs can skip both) and see <a href="/rakkii-cars-guide/chapters/09-parts-inventory-canvass-restock-payables">Chapter 9</a>.</p><p><img src="'+l+'" alt="Work lines card with labor and part lines, Who pays, Qty, Cost and Sell"></p><h3 id="customer-estimate-and-margin-warning-quote-tab" tabindex="-1">Customer estimate and margin warning (Quote tab) <a class="header-anchor" href="#customer-estimate-and-margin-warning-quote-tab" aria-label="Permalink to &quot;Customer estimate and margin warning (Quote tab)&quot;">​</a></h3><ol><li>Open the <strong>Quote</strong> tab. The <strong>Customer estimate</strong> shows sell prices only. If the job has no lines yet, the tab says to add work and parts lines first, with a <strong>Go to Work tab</strong> button.</li><li>Check the margin. The job header shows it as a chip, for example <strong>Margin 167% on cost</strong>. <ul><li>Margin is counted <strong>on cost</strong>: (sell − cost) ÷ cost. A ₱300 cost sold at ₱800 is 167% on cost. The shop&#39;s minimum uses the same basis.</li><li>If it is under the shop&#39;s minimum (30% by default) you see &quot;Margin X% on cost is under the 30% floor.&quot;</li><li>In <strong>Warn</strong> mode you can still save; the job is flagged.</li><li>In <strong>Block</strong> mode the owner (or admin) must type an <strong>Override reason</strong> to save.</li></ul></li><li>Press <strong>Create quote</strong> and confirm. The status becomes <strong>Quoted</strong> (or press <strong>Mark quoted</strong>).</li><li><strong>Print estimate</strong> for a paper copy.</li></ol><div class="warning custom-block"><p class="custom-block-title">Changed the lines after quoting?</p><p>If you add, remove or change approved lines after the quote, the Quote and Work tabs show &quot;Work lines changed since the last quote (PHP … now vs PHP … quoted). Create a new quote so the customer sees the new total.&quot; Create a new quote before you ask the customer to pay.</p></div><h2 id="_5-4-customer-approval-through-the-customer-portal" tabindex="-1">5.4 Customer approval through the Customer Portal <a class="header-anchor" href="#_5-4-customer-approval-through-the-customer-portal" aria-label="Permalink to &quot;5.4 Customer approval through the Customer Portal&quot;">​</a></h2><ol><li>On the Quote tab press <strong>Copy customer link</strong> and send it by SMS, Messenger or email.</li><li>The customer opens the pay link on the Customer Portal (for example <code>https://rakkii-web-int.web.app/pay/&lt;token&gt;</code>). They see the job, plate, estimate total and <strong>Your share (Balance due)</strong>.</li><li>They press <strong>Approve estimate</strong> or <strong>Decline estimate</strong>. Approving or declining takes no payment.</li><li>Back in Ops the Quote tab shows &quot;Last quote: … · Approved by … · date&quot;.</li></ol><p>The same page lets the customer <strong>Upload payment screenshot</strong> for GCash or Maya. Those arrive in <strong>Finance › Payments › Pending proofs</strong> for you to confirm (<a href="/rakkii-cars-guide/chapters/08-lane-4-billing-chain-receivables-storage-credit-notes">Chapter 8</a>). While a proof is waiting, the job&#39;s next-step banner says &quot;The customer sent a payment proof. Confirm or reject it.&quot; and the <strong>Pay</strong> and <strong>Release</strong> tabs show a warning with a link straight to the pending proofs.</p><p><img src="'+d+'" alt="Customer Portal pay page with Approve estimate / Decline estimate"></p><h2 id="_5-5-record-the-50-down-payment" tabindex="-1">5.5 Record the 50% down payment <a class="header-anchor" href="#_5-5-record-the-50-down-payment" aria-label="Permalink to &quot;5.5 Record the 50% down payment&quot;">​</a></h2><p>The <strong>Pay › Money</strong> card shows <strong>Customer owes</strong>, <strong>Cash in</strong>, <strong>DP required</strong>, <strong>DP collected</strong> and <strong>DP still due</strong>. Private jobs default to <strong>50%</strong> of the customer share.</p><ol><li>Open <strong>Pay › Record a payment</strong>.</li><li><strong>Who paid</strong>: Customer. <strong>Amount</strong>: the down payment. <strong>Method</strong>: Cash, GCash, Maya, Bank transfer, Card or Other.</li><li>For bank transfers pick the <strong>Bank account</strong> code, and fill <strong>Particular</strong> (often the plate) and <strong>Reference</strong>.</li><li>Optionally set <strong>Deposited to</strong> (which shop account the money went into).</li><li>Press <strong>Record payment</strong>, then <strong>Print acknowledgement</strong> for the customer.</li></ol><p><strong>Down payment rules</strong></p><p>The <strong>Down payment</strong> card on the Pay tab says in plain words whether the deposit holds the job: &quot;Needed before work starts&quot;, &quot;Needed before the car is released&quot; or &quot;For reference only, it does not hold the job&quot;, plus whether it is covered.</p><ul><li>The owner decides per nature whether the deposit blocks anything: <strong>Does not block</strong> (default), <strong>Before work</strong> or <strong>Before release</strong> (Chapter 13).</li><li>To change one job, open <strong>Change the down payment</strong>, use <strong>Percent override</strong> or <strong>Amount override</strong> with a <strong>Reason</strong>, then <strong>Save down payment</strong>.</li><li>If the deposit blocks work and you must start anyway, the owner (or admin) enters a <strong>Bypass reason to start work without the deposit</strong>.</li></ul><h2 id="_5-6-assign-the-technician-and-start-work" tabindex="-1">5.6 Assign the technician and start work <a class="header-anchor" href="#_5-6-assign-the-technician-and-start-work" aria-label="Permalink to &quot;5.6 Assign the technician and start work&quot;">​</a></h2><ol><li><strong>Work › Technicians and dates</strong>: pick the technician(s), choose a <strong>Reason for change</strong>, press <strong>Save technicians</strong>. Changes are kept in <strong>Assignment history</strong>. <ul><li>Technicians are listed first. The Owner and Admin can still be assigned: press <strong>Show owner and admin</strong> (they show anyway if one is already on the job).</li></ul></li><li>You don&#39;t need to type the work dates. The card shows the dates the app recorded in one line: <strong>Car in</strong>, <strong>Started</strong>, <strong>Done</strong>, <strong>Car out</strong>, <strong>Billed</strong> and <strong>Paid</strong>. They come from the status moves, the release, the first posted invoice and the payment that cleared the balance. <ul><li>To correct one, open <strong>Edit dates</strong>, change it and press <strong>Save</strong>. A typed date always wins.</li><li>The Job order box and the printed job order use the same dates.</li></ul></li><li>Apply a <strong>Bay checklist</strong> template (<strong>Template › Apply template</strong>) so the technician has steps to tick.</li><li>Press <strong>Start work</strong>. Status: <strong>Under repair</strong>. The banner changes to &quot;Finish work and send to QC.&quot;</li></ol><p><img src="'+h+'" alt="Job header after Start work: Under repair banner, Step 3 of 7, Send to QC as the main button, Ready for pickup locked"></p><h2 id="_5-7-bay-checklist-and-qc-photos" tabindex="-1">5.7 Bay checklist and QC photos <a class="header-anchor" href="#_5-7-bay-checklist-and-qc-photos" aria-label="Permalink to &quot;5.7 Bay checklist and QC photos&quot;">​</a></h2><p>The technician ticks the <strong>Bay checklist</strong> and uploads the four <strong>QC photos</strong> — <strong>Front</strong>, <strong>Rear</strong>, <strong>Left side (LS)</strong>, <strong>Right side (RS)</strong> (<a href="/rakkii-cars-guide/chapters/02-technician-daily-guide#_2-8-uploading-the-four-qc-photos">Chapter 2</a>).</p><ol><li>When work is done, press <strong>Send to QC</strong>. While QC photos are missing, <strong>Send to QC</strong> is the main button and <strong>Ready for pickup</strong> stays greyed out with the reason &quot;Need 4 QC photos before Ready/Released (have 0).&quot; <ul><li>If checklist steps are still open, the app asks first: &quot;Send to QC with steps open? 1 of 2 checklist steps are not ticked yet.&quot; Press <strong>Send to QC anyway</strong> or go back and tick them.</li></ul></li><li>On <strong>Quality check</strong> the banner lists the missing angles (&quot;Take the missing QC photos (Front, Rear). 2 of 4 done.&quot;). Once all four are in, <strong>Ready for pickup</strong> unlocks and the banner says &quot;Pass QC and mark ready for pickup.&quot;</li><li>If photos truly cannot be taken, the owner types a <strong>QC override reason</strong> and <strong>Save QC override</strong>.</li><li>Print the <strong>QC summary</strong> (<strong>More papers › QC summary</strong>) if the customer wants it.</li></ol><h3 id="printing" tabindex="-1">Printing papers <a class="header-anchor" href="#printing" aria-label="Permalink to &quot;Printing papers {#printing}&quot;">​</a></h3><p>The <strong>Job order</strong> box (Work tab) has two buttons instead of a long row:</p><ul><li><strong>Print job order</strong> for the bay.</li><li><strong>More papers ▾</strong>, grouped as: <ul><li><strong>For the customer</strong> — Estimate, Customer invoice, Payment instructions, Payment acknowledgement, Acceptance</li><li><strong>For the shop</strong> — Gate pass, QC summary, Insurer invoice, Release of Claim (insurance jobs)</li><li><strong>Forms to fill</strong> — Pickup/Delivery waiver, Intake checklist</li></ul></li></ul><p><img src="'+g+'" alt="More papers menu open: For the customer, For the shop and Forms to fill, with the recorded dates under it"></p><p>The Quote, Pay and Release tabs keep their own print buttons for the paper you need at that step. On the Pay tab, the on-screen paper previews are folded behind <strong>Show … preview</strong> buttons; printing is the same.</p><div class="tip custom-block"><p class="custom-block-title">Printing from a phone</p><p>Phones can&#39;t print a PDF inside the app, so on a phone each print saves the PDF instead, named after the paper and the plate (for example <code>Gate pass DEMO 101.pdf</code>). Open it from the download bar to print or share it. Computers and laptops still get the print dialog.</p></div><h2 id="_5-8-create-and-post-the-customer-invoice" tabindex="-1">5.8 Create and post the customer invoice <a class="header-anchor" href="#_5-8-create-and-post-the-customer-invoice" aria-label="Permalink to &quot;5.8 Create and post the customer invoice&quot;">​</a></h2><ol><li>Open <strong>Pay › Invoices</strong>. The app offers <strong>Bill customer PHP …</strong> based on the approved customer lines.</li><li>Press it and confirm <strong>Create invoice</strong> (&quot;This posts an invoice. Undoing it later needs a void or a credit note.&quot;). The invoice is created <strong>Posted</strong>, with a number from the VAT or Non-VAT series (for example <code>V-0018</code>).</li><li>Press <strong>Print customer invoice</strong>. <strong>Print payment instructions</strong> gives the customer the pay link, GCash/Maya and bank details.</li></ol><p>Posting an invoice does not change the job status.</p><h2 id="_5-9-record-the-final-balance" tabindex="-1">5.9 Record the final balance <a class="header-anchor" href="#_5-9-record-the-final-balance" aria-label="Permalink to &quot;5.9 Record the final balance&quot;">​</a></h2><ol><li><strong>Pay › Record a payment</strong>, <strong>Who paid</strong>: Customer.</li><li>Press <strong>Fill customer balance</strong> to enter exactly what is left, pick the <strong>Method</strong>, and <strong>Apply to invoice</strong>.</li><li><strong>Record payment</strong> and confirm (&quot;Record PHP 800.00 from the customer?&quot;). <strong>Customer owes</strong> should read PHP 0.00 and the banner changes to &quot;Release the car.&quot;</li></ol><p><img src="'+c+'" alt="Pay tab Money card after the final payment (Customer owes PHP 0.00) and the Down payment card"></p><p>By default the car is held until the customer balance is zero (&quot;Hold the car until the customer has paid: Yes&quot; on Overview).</p><h2 id="_5-10-release-checklist-gate-pass-and-acceptance" tabindex="-1">5.10 Release checklist, gate pass and acceptance <a class="header-anchor" href="#_5-10-release-checklist-gate-pass-and-acceptance" aria-label="Permalink to &quot;5.10 Release checklist, gate pass and acceptance&quot;">​</a></h2><ol><li>Open the <strong>Release</strong> tab. If the job is not yet <strong>Ready for pickup</strong> it says &quot;Move the job to Ready for pickup first.&quot; The tab shows <strong>QC photos: 4/4</strong> and <strong>Customer balance</strong>.</li><li>Print what the customer and guard need, right from the Release tab: <strong>Print gate pass</strong> for the guard and <strong>Print customer invoice</strong> for the customer. After release the tab also offers <strong>Print acceptance</strong> (acceptance and satisfaction of repair) for the customer to sign. <ul><li>The gate pass shows <strong>Released on</strong> with the date and time (or &quot;Not released yet&quot;).</li><li>The acceptance fills <strong>Work completed</strong> from the day the job first reached QC, Ready or Released, unless someone typed a date.</li></ul></li><li>Tick the three release checks: <ul><li><strong>Keys logged</strong></li><li><strong>Documents in / out</strong></li><li><strong>Customer signed release</strong></li></ul></li><li>Press <strong>Release car</strong> and confirm (&quot;The car leaves the shop and the job becomes read-only.&quot;). The job becomes <strong>Released</strong> and the tab shows &quot;Released on … · Released by …&quot;.</li></ol><div class="tip custom-block"><p class="custom-block-title">Rakkii&#39;s hand-over routine</p><p>Before ticking <strong>Customer signed release</strong>, confirm the shop&#39;s hand-over steps: the customer signed the acceptance form, the old replaced parts were returned to the customer, and the car was washed and vacuumed. Add these as steps in a &quot;Release prep&quot; bay checklist template (Admin › Shop settings › Company › Lists › Checklist templates) so they are ticked and logged on every job.</p></div><p><strong>What blocks release (and who can pass it)</strong></p><table tabindex="0"><thead><tr><th>Block</th><th>Message</th><th>Way through</th></tr></thead><tbody><tr><td>Not Ready</td><td>&quot;Job must be in ready status before release.&quot;</td><td>Finish QC, mark Ready</td></tr><tr><td>Customer balance open</td><td>&quot;Customer still owes. Default is to hold the car.&quot;</td><td>Collect, or <strong>Owner override</strong> + reason</td></tr><tr><td>Down payment before release</td><td>&quot;Down payment shortfall … still due before release.&quot;</td><td>Collect, or owner override</td></tr><tr><td>QC photos missing</td><td>names the missing angle</td><td>Upload, or QC override reason</td></tr><tr><td>Release checks not ticked</td><td>&quot;Keys logged, documents in/out and customer signed must all be ticked…&quot;</td><td>Tick, or owner override + reason</td></tr><tr><td>Invoices not posted (if the job holds for invoices)</td><td>&quot;Post the customer invoice before release.&quot;</td><td>Post, or owner reason &quot;Reason to release before invoices are posted&quot;</td></tr></tbody></table><p><img src="'+p+'" alt="Release tab of a Ready job: QC photos, customer balance, Keys logged, Documents in / out, Customer signed release"></p><h2 id="_5-11-mark-the-job-as-done" tabindex="-1">5.11 Mark the job as done <a class="header-anchor" href="#_5-11-mark-the-job-as-done" aria-label="Permalink to &quot;5.11 Mark the job as done&quot;">​</a></h2><p>A car can leave before everything is settled, for example while an insurer still has to pay. So <strong>Released</strong> means the car is out, and <strong>Done</strong> means nothing is left.</p><ol><li>After release, check the <strong>Not done yet</strong> box on the job (see <a href="#progress">Status, steps and what&#39;s left</a>).</li><li>Press <strong>Mark as done</strong> (or <strong>Mark invoiced</strong> first if you track that step). <ul><li><strong>Only open checklist items block it.</strong> Money still owed is listed but does not block, because insurers can pay long after release.</li><li>With checklist items open, the button is off for everyone except the Owner. The Owner can still mark it done by typing a reason; it is saved in the job&#39;s <strong>Status log</strong> as &quot;Done with N checklist items open: …&quot;.</li></ul></li><li>A done job is read-only. Its car, payments and invoices stay in the customer&#39;s <strong>Service history</strong>. Once a job is released or done, the Overview hides the date edit boxes and keeps the summary lines.</li><li>Set <strong>Remind me</strong> (3, 6 or 12 months) on Overview if the customer should get a service reminder email.</li></ol>',77)])])}const P=e(u,[["render",m]]);export{q as __pageData,P as default};
